function validate([root, nodes]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs a root.';
  // Every value must sit in a child slot of an earlier node.
  let slots = 1;
  for (let i = 0; i < root.length; i++) {
    if (i >= slots) return 'The level-order array has values with no parent.';
    if (root[i] !== null) slots += 2;
  }
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Node values are whole numbers between -10^9 and 10^9.';
  const present = new Set(values);
  if (present.size !== values.length) return 'Node values must be unique.';
  if (!Array.isArray(nodes) || nodes.length === 0) return 'nodes needs at least one node.';
  if (new Set(nodes).size !== nodes.length) return 'The entries of nodes must be distinct.';
  if (nodes.some(v => !present.has(v))) return 'Every entry of nodes must be a value in the tree.';
  return null;
}

