function adapt(input, solve, kit) {
  const [values, chosen] = input;
  const root = kit.toTree(values);
  // Collect the nodes with an explicit stack so that deep trees need no recursion here.
  const nodes = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    nodes.push(node);
    if (node.right) stack.push(node.right);
    if (node.left) stack.push(node.left);
  }
  const byValue = new Map(nodes.map(node => [node.val, node]));
  const links = nodes.map(node => [node.val, node.left, node.right]);
  const result = solve(root, chosen.map(v => byValue.get(v)));
  const intact = nodes.every((node, i) => node.val === links[i][0] && node.left === links[i][1] && node.right === links[i][2]);
  if (!intact) throw new Error('The tree must not be modified.');
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (result === null) return null;
  if (!new Set(nodes).has(result)) throw new Error('Return a node of the tree.');
  return result.val;
}

