function lowestCommonAncestor(root, nodes) {
  // Record every node's parent and depth with a breadth-first walk.
  const parent = new Map([[root, null]]);
  const depth = new Map([[root, 0]]);
  const queue = [root];
  for (let i = 0; i < queue.length; i++) {
    for (const child of [queue[i].left, queue[i].right]) {
      if (child) { parent.set(child, queue[i]); depth.set(child, depth.get(queue[i]) + 1); queue.push(child); }
    }
  }
  // Combine the nodes one at a time: lift the deeper of two nodes, then lift both until they meet.
  let answer = nodes[0];
  for (const node of nodes.slice(1)) {
    let x = answer, y = node;
    while (depth.get(x) > depth.get(y)) x = parent.get(x);
    while (depth.get(y) > depth.get(x)) y = parent.get(y);
    while (x !== y) { x = parent.get(x); y = parent.get(y); }
    answer = x;
  }
  return answer;
}

