function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(90) : 1 + pick(10);
  const deep = rand() < 0.35;
  const span = size === 'large' || rand() < 0.3 ? 1000000000 : 25;
  const used = new Set();
  const fresh = () => { for (;;) { const v = pick(2 * span + 1) - span; if (!used.has(v)) { used.add(v); return v; } } };
  const nodes = [{ val: fresh(), left: null, right: null }];
  while (nodes.length < n) {
    // Deep trees grow from the newest nodes; bushy trees attach a child anywhere.
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    parent[side] = { val: fresh(), left: null, right: null };
    nodes.push(parent[side]);
  }
  const root = [];
  const queue = [nodes[0]];
  for (let k = 0; k < queue.length; k++) {
    root.push(queue[k] ? queue[k].val : null);
    if (queue[k]) queue.push(queue[k].left, queue[k].right);
  }
  while (root[root.length - 1] === null) root.pop();
  // Choose how many nodes to ask about, then take that many distinct ones at random.
  const mode = rand();
  const count = size === 'small' ? 1 + pick(Math.min(n, 4)) : mode < 0.25 ? 1 : mode < 0.5 ? 2 : mode < 0.75 ? 3 + pick(20) : 1 + pick(n);
  const order = nodes.map((_, i) => i);
  for (let i = 0; i < count; i++) {
    const j = i + pick(n - i);
    [order[i], order[j]] = [order[j], order[i]];
  }
  return [root, order.slice(0, count).map(i => nodes[i].val)];
}
